const PAGE = "<!doctype html>\n<html lang=\"de\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"robots\" content=\"noindex, nofollow, noarchive\">\n  <meta name=\"theme-color\" content=\"#082d46\">\n  <meta name=\"description\" content=\"Ästhetische Medizin bei Robert Tobis: individuelle ärztliche Therapieauswahl mit Eigenblutbehandlung und Blutbehandlung (PRP/i-PRF), Botox (Botulinumtoxin) sowie Hyaluronsäure.\">\n  <title>Blutbehandlung &amp; Botox | Ästhetische Medizin Robert Tobis</title>\n  <style>:root {\n  --ink: #0c3149;\n  --deep: #06273d;\n  --blue: #1a729d;\n  --sky: #7ec8e8;\n  --gold: #d6ad6c;\n  --mist: #e9f5fa;\n  --ice: #f5fbfd;\n  --white: #fff;\n  --sand: #f2eee8;\n  --muted: #607787;\n  --line: rgba(12, 49, 73, .15);\n  --shadow: 0 24px 70px rgba(3, 35, 55, .15);\n  --display: \"Iowan Old Style\", \"Baskerville\", \"Times New Roman\", serif;\n  --sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\n\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody { margin: 0; color: var(--ink); background: var(--ice); font-family: var(--sans); line-height: 1.6; }\nbutton, input, textarea, select { font: inherit; }\nbutton, a { -webkit-tap-highlight-color: transparent; }\nimg { display: block; max-width: 100%; }\n.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }\n.skip-link { position: fixed; top: -60px; left: 16px; z-index: 1000; background: white; color: var(--deep); padding: 10px 16px; border-radius: 0 0 8px 8px; transition: top .2s; }\n.skip-link:focus { top: 0; }\n\n.site-header { height: 88px; padding: 0 clamp(24px, 5vw, 80px); display: flex; align-items: center; justify-content: space-between; position: absolute; inset: 0 0 auto; z-index: 20; color: white; border-bottom: 1px solid rgba(255,255,255,.25); }\n.brand { color: inherit; text-decoration: none; display: flex; align-items: center; gap: 13px; }\n.brand-mark { width: 42px; height: 42px; display: grid; place-items: center; border: 1px solid rgba(255,255,255,.58); border-radius: 50%; font-family: var(--display); letter-spacing: -.05em; font-size: 17px; }\n.brand-text { display: grid; line-height: 1.12; }\n.brand-name { font-family: var(--display); font-size: clamp(22px, 2vw, 28px); font-weight: 600; letter-spacing: .02em; color: #e4f7ff; text-shadow: 0 2px 14px rgba(0,20,34,.5); }\n.brand-caption { font-size: 10px; letter-spacing: .22em; text-transform: uppercase; opacity: .88; margin-top: 4px; }\n.navigation { display: flex; align-items: center; gap: clamp(22px, 3vw, 46px); }\n.navigation > a { color: inherit; text-decoration: none; font-size: 13px; letter-spacing: .08em; position: relative; }\n.navigation > a::after { content: \"\"; position: absolute; height: 1px; left: 0; right: 100%; bottom: -7px; background: currentColor; transition: right .25s; }\n.navigation > a:hover::after, .navigation > a:focus-visible::after { right: 0; }\n.menu-toggle { display: none; background: none; border: 0; padding: 8px; }\n.menu-toggle > span:not(.sr-only) { width: 26px; height: 1px; background: white; margin: 5px; display: block; }\n\n.button { border: 0; border-radius: 0; background: var(--deep); color: white; min-height: 52px; padding: 0 24px; display: inline-flex; align-items: center; justify-content: center; gap: 28px; cursor: pointer; text-decoration: none; font-size: 12px; letter-spacing: .12em; text-transform: uppercase; transition: transform .2s, background .2s, color .2s; }\n.button:hover { transform: translateY(-2px); background: #124b6b; }\n.button:focus-visible, button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible { outline: 3px solid #f1bc66; outline-offset: 3px; }\n.button-small { min-height: 42px; padding: 0 18px; background: rgba(255,255,255,.12); border: 1px solid rgba(255,255,255,.55); }\n\n.hero { min-height: 100svh; position: relative; overflow: hidden; color: white; background: var(--deep); }\n.hero-media { position: absolute; inset: 0; background-image: url(\"/assets/hero-premium.webp\"); background-size: cover; background-position: center center; transform: scale(1.005); }\n.hero-shade { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(2,30,49,.86) 0%, rgba(3,40,63,.58) 40%, rgba(6,42,63,.04) 72%), linear-gradient(0deg, rgba(5,35,52,.38), transparent 42%); }\n.hero-content { position: relative; z-index: 2; min-height: 100svh; max-width: 760px; display: flex; flex-direction: column; justify-content: center; padding: 150px 5vw 126px; margin-left: clamp(0px, 4vw, 64px); }\n.eyebrow, .section-index { margin: 0 0 24px; font-size: 10px; letter-spacing: .28em; text-transform: uppercase; font-weight: 650; }\n.eyebrow { color: #bfe7f6; }\nh1, h2, h3, p { margin-top: 0; }\nh1, h2 { font-family: var(--display); font-weight: 400; letter-spacing: -.045em; line-height: .94; }\nh1 { font-size: clamp(64px, 8vw, 124px); margin-bottom: 32px; max-width: 830px; }\nh1 em, h2 em { font-weight: 400; color: var(--sky); }\n.hero-copy { max-width: 570px; font-size: clamp(17px, 1.4vw, 21px); color: rgba(255,255,255,.85); line-height: 1.6; }\n.hero-actions { display: flex; align-items: center; gap: 32px; margin-top: 26px; }\n.hero-actions .button { background: white; color: var(--deep); }\n.hero-actions .button:hover { background: var(--sky); }\n.text-link { color: white; font-size: 12px; letter-spacing: .12em; text-transform: uppercase; text-decoration: none; border-bottom: 1px solid rgba(255,255,255,.45); padding: 14px 0 8px; }\n.hero-credential { position: absolute; z-index: 2; right: 5vw; bottom: 40px; display: flex; gap: 18px; align-items: center; padding: 15px 18px; border-left: 2px solid #8cd4ef; background: rgba(3,38,59,.42); backdrop-filter: blur(7px); }\n.credential-line { height: 1px; width: 70px; background: rgba(255,255,255,.55); }\n.hero-credential div:last-child { display: grid; line-height: 1.3; text-align: right; }\n.hero-credential strong { font-family: var(--display); font-size: clamp(25px, 2.4vw, 34px); font-weight: 500; color: #dff5ff; letter-spacing: .015em; text-shadow: 0 2px 14px rgba(0,20,34,.46); }\n.hero-credential span { font-size: 10px; text-transform: uppercase; letter-spacing: .15em; opacity: .88; margin-top: 5px; }\n\n.section-shell { width: min(1320px, calc(100% - 10vw)); margin: 0 auto; }\n.expertise { padding-top: clamp(88px, 10vw, 160px); padding-bottom: clamp(88px, 10vw, 160px); display: grid; grid-template-columns: 1.05fr .72fr; gap: clamp(60px, 10vw, 150px); align-items: center; }\n.section-index { color: var(--blue); }\nh2 { font-size: clamp(48px, 6vw, 86px); margin-bottom: 38px; }\n.expertise-copy .lead { font-family: var(--display); font-size: clamp(22px, 2.2vw, 31px); line-height: 1.45; color: var(--ink); }\n.expertise-copy > p:not(.section-index):not(.lead) { max-width: 660px; color: var(--muted); font-size: 16px; }\n.principles { display: flex; flex-wrap: wrap; margin-top: 38px; gap: 10px; }\n.principles span, .result-tags span { font-size: 10px; letter-spacing: .12em; text-transform: uppercase; padding: 9px 13px; border: 1px solid var(--line); border-radius: 99px; }\n.care-path { display: grid; grid-template-columns: repeat(4, 1fr); margin-top: 38px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }\n.care-path > div { padding: 18px 12px 17px 0; display: grid; border-right: 1px solid var(--line); }\n.care-path > div + div { padding-left: 14px; }\n.care-path > div:last-child { border-right: 0; }\n.care-path b { color: var(--gold); font-size: 9px; letter-spacing: .14em; margin-bottom: 6px; }\n.care-path strong { font-family: var(--display); font-size: 18px; font-weight: 400; }\n.care-path span { color: var(--muted); font-size: 9px; line-height: 1.35; margin-top: 4px; }\n.expertise-image { margin: 0; position: relative; }\n.expertise-image::before { content: \"\"; position: absolute; inset: 18px -18px -18px 18px; border: 1px solid #9ccce0; z-index: -1; }\n.expertise-image img { width: 100%; aspect-ratio: 3 / 4; object-fit: cover; }\n.expertise-image figcaption { display: flex; justify-content: space-between; padding-top: 18px; color: var(--muted); font-size: 9px; letter-spacing: .16em; text-transform: uppercase; }\n\n.services { background: var(--deep); color: white; padding: clamp(90px, 10vw, 150px) 0 80px; }\n.services-inner { width: min(1420px, calc(100% - 8vw)); }\n.section-heading { display: grid; grid-template-columns: 1.4fr .6fr; gap: 8vw; align-items: end; margin-bottom: 64px; }\n.section-heading h2 { margin: 0; }\n.section-index.light { color: #9dd6ef; }\n.section-heading > p { color: rgba(255,255,255,.66); max-width: 500px; margin: 0 0 8px; }\n.service-grid { display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid rgba(255,255,255,.17); border-bottom: 1px solid rgba(255,255,255,.17); }\n.service-card { min-height: 570px; padding: 36px clamp(26px, 3vw, 48px) 42px; display: flex; flex-direction: column; border-right: 1px solid rgba(255,255,255,.17); position: relative; transition: background .3s, transform .3s; }\n.service-card:last-child { border-right: 0; }\n.service-card:hover { background: rgba(255,255,255,.045); transform: translateY(-4px); }\n.service-card.featured { background: linear-gradient(160deg, rgba(49,138,179,.22), rgba(255,255,255,.025)); }\n.service-number { color: #90cce7; font-size: 10px; letter-spacing: .18em; }\n.service-icon { width: 72px; height: 72px; border: 1px solid rgba(255,255,255,.2); border-radius: 50%; display: grid; place-items: center; margin: 38px 0 32px; }\n.service-icon svg { width: 38px; height: 38px; fill: none; stroke: #a8daed; stroke-width: 1.3; }\n.service-card h3 { font-family: var(--display); font-size: clamp(32px, 3vw, 45px); font-weight: 400; margin-bottom: 16px; }\n.service-card p { color: rgba(255,255,255,.66); font-size: 14px; }\n.service-card ul { margin: 16px 0 30px; padding: 0; list-style: none; color: rgba(255,255,255,.82); font-size: 13px; }\n.service-card li { padding: 7px 0 7px 16px; position: relative; border-bottom: 1px solid rgba(255,255,255,.08); }\n.service-card li::before { content: \"\"; width: 4px; height: 4px; border-radius: 50%; background: var(--sky); position: absolute; left: 0; top: 16px; }\n.botox-map-link { width: 100%; min-height: 72px; margin: 4px 0 18px; padding: 8px 12px 8px 8px; color: white; border: 1px solid rgba(255,255,255,.2); background: rgba(255,255,255,.035); cursor: pointer; display: grid; grid-template-columns: 54px 1fr auto; align-items: center; gap: 12px; text-align: left; text-decoration: none; font: inherit; transition: background .2s, border-color .2s, transform .2s; }\n.botox-map-link:hover { background: rgba(126,200,232,.13); border-color: rgba(126,200,232,.55); transform: translateY(-2px); }\n.map-thumb { width: 54px; height: 54px; overflow: hidden; background: var(--mist); }\n.map-thumb img { width: 100%; height: 100%; object-fit: cover; object-position: center 34%; }\n.botox-map-link > span:nth-child(2) { display: grid; }\n.botox-map-link strong { font-family: var(--display); font-size: 18px; font-weight: 400; }\n.botox-map-link small { color: rgba(255,255,255,.55); font-size: 8px; letter-spacing: .1em; text-transform: uppercase; margin-top: 3px; }\n.botox-map-link b { color: var(--sky); font-weight: 400; }\n.treatment-links { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin: 4px 0 18px; }\n.treatment-link { min-height: 70px; padding: 12px 12px; border: 1px solid rgba(255,255,255,.2); color: white; background: rgba(255,255,255,.035); cursor: pointer; display: grid; grid-template-columns: 1fr auto; text-align: left; transition: background .2s, border-color .2s, transform .2s; }\n.treatment-link span { font-family: var(--display); font-size: 19px; line-height: 1.1; }\n.treatment-link small { grid-column: 1; color: rgba(255,255,255,.55); font-size: 8px; letter-spacing: .12em; text-transform: uppercase; margin-top: 5px; }\n.treatment-link b { grid-column: 2; grid-row: 1 / 3; align-self: center; color: var(--sky); font-weight: 400; }\n.treatment-link:hover { background: rgba(126,200,232,.13); border-color: rgba(126,200,232,.55); transform: translateY(-2px); }\n.card-link { margin-top: auto; color: white; background: none; border: 0; border-bottom: 1px solid rgba(255,255,255,.25); padding: 12px 0; text-align: left; display: flex; justify-content: space-between; cursor: pointer; font-size: 10px; text-transform: uppercase; letter-spacing: .14em; }\n.medical-note { margin: 24px 0 0; text-align: right; color: rgba(255,255,255,.48); font-size: 11px; }\n\n.prices { background: white; padding: clamp(90px, 10vw, 150px) 0; }\n.prices-shell { width: min(1380px, calc(100% - 8vw)); }\n.prices-heading { display: grid; grid-template-columns: 1.35fr .65fr; gap: 8vw; align-items: end; margin-bottom: 62px; }\n.prices-heading h2 { margin: 0; }\n.prices-heading > p { max-width: 510px; margin: 0 0 8px; color: var(--muted); }\n.price-groups { display: grid; grid-template-columns: 1fr 1fr; border: 1px solid var(--line); box-shadow: 0 26px 70px rgba(9,53,79,.08); }\n.price-group { padding: clamp(32px, 4vw, 58px); }\n.price-group + .price-group { border-left: 1px solid var(--line); }\n.price-group-accent { background: linear-gradient(145deg, #f0f9fc, #e1f1f7); }\n.price-group-head { display: flex; align-items: baseline; gap: 20px; padding-bottom: 26px; border-bottom: 1px solid var(--line); }\n.price-group-head span { color: var(--gold); font-size: 9px; letter-spacing: .16em; }\n.price-group-head h3 { margin: 0; font-family: var(--display); font-size: clamp(30px, 3vw, 43px); font-weight: 400; line-height: 1.08; }\n.price-list { margin: 0; }\n.price-list > div { min-height: 76px; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 22px; align-items: center; border-bottom: 1px solid var(--line); }\n.price-list dt { color: var(--ink); font-size: 15px; }\n.price-list dt small { display: block; margin-top: 2px; color: var(--muted); font-size: 10px; letter-spacing: .08em; text-transform: uppercase; }\n.price-list dd { margin: 0; color: var(--blue); font-family: var(--display); font-size: clamp(25px, 2.4vw, 34px); white-space: nowrap; }\n.price-list .price-on-request { font-family: var(--sans); font-size: 11px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; }\n.price-note { display: flex; align-items: center; justify-content: space-between; gap: 34px; margin-top: 30px; padding: 24px 0; border-top: 1px solid var(--line); }\n.price-note p { max-width: 850px; margin: 0; color: var(--muted); font-size: 12px; }\n.price-note .button { flex: 0 0 auto; }\n\n.guide { background: #eef8fb; padding: clamp(90px, 10vw, 150px) 0 0; }\n.guide-shell { width: min(1380px, calc(100% - 8vw)); }\n.guide-intro { display: grid; grid-template-columns: 1fr 1.3fr .8fr; gap: 5vw; align-items: end; margin-bottom: 62px; }\n.guide-intro .section-index { align-self: start; margin-top: 13px; }\n.guide-intro h2 { margin: 0; }\n.guide-intro > p:last-child { color: var(--muted); margin: 0 0 8px; }\n.guide-panel { display: grid; grid-template-columns: .72fr 1.28fr; background: white; box-shadow: var(--shadow); min-height: 560px; }\n.concern-list { padding: 28px 0; background: #dff0f7; }\n.concern { width: 100%; min-height: 92px; border: 0; border-bottom: 1px solid rgba(12,49,73,.12); background: transparent; color: var(--ink); padding: 0 38px; text-align: left; display: flex; align-items: center; gap: 25px; cursor: pointer; font-family: var(--display); font-size: 23px; transition: background .2s, color .2s, padding .2s; }\n.concern span { font-family: var(--sans); font-size: 9px; letter-spacing: .16em; color: var(--blue); }\n.concern:hover, .concern.active { background: var(--deep); color: white; padding-left: 48px; }\n.concern.active span, .concern:hover span { color: var(--sky); }\n.guide-result { padding: clamp(42px, 5vw, 76px); display: flex; flex-direction: column; }\n.result-kicker { color: var(--blue); font-size: 9px; letter-spacing: .22em; text-transform: uppercase; margin-bottom: 22px; }\n.guide-result h3 { font-family: var(--display); font-size: clamp(46px, 5vw, 72px); font-weight: 400; line-height: 1; margin-bottom: 26px; }\n.guide-result > p { font-family: var(--display); font-size: clamp(19px, 2vw, 25px); line-height: 1.5; max-width: 760px; }\n.result-tags { display: flex; flex-wrap: wrap; gap: 8px; margin: 6px 0 30px; }\n.result-footer { border-top: 1px solid var(--line); padding-top: 26px; margin-top: auto; display: flex; justify-content: space-between; gap: 30px; align-items: center; }\n.result-footer p { color: var(--muted); font-size: 12px; max-width: 530px; margin: 0; }\n.result-footer .button { flex: 0 0 auto; }\n.contact-strip { margin-top: clamp(80px, 9vw, 130px); background: var(--blue); color: white; padding: 52px clamp(28px, 5vw, 72px); display: flex; align-items: center; justify-content: space-between; gap: 30px; }\n.contact-strip span { font-size: 9px; letter-spacing: .22em; text-transform: uppercase; color: #c8eaf7; }\n.contact-strip h3 { font-family: var(--display); font-size: clamp(28px, 3.2vw, 46px); font-weight: 400; line-height: 1.15; margin: 8px 0 0; }\n.button-light { background: white; color: var(--deep); }\n\n.site-footer { background: var(--deep); color: white; padding: 70px 5vw 34px; display: grid; grid-template-columns: 1.3fr 1fr auto; align-items: center; gap: 30px; }\n.footer-brand { display: flex; gap: 14px; align-items: center; }\n.footer-brand > div { display: grid; line-height: 1.2; }\n.footer-brand strong { font-family: var(--display); font-size: 22px; font-weight: 400; }\n.footer-brand span:last-child { font-size: 9px; letter-spacing: .18em; text-transform: uppercase; color: rgba(255,255,255,.58); margin-top: 4px; }\n.light-mark { border-color: rgba(255,255,255,.35); }\n.site-footer > p { margin: 0; color: rgba(255,255,255,.6); font-size: 12px; }\n.footer-links { display: flex; gap: 20px; }\n.footer-links button { background: none; border: 0; color: rgba(255,255,255,.72); padding: 4px 0; cursor: pointer; font-size: 11px; }\n.site-footer small { grid-column: 1 / -1; border-top: 1px solid rgba(255,255,255,.12); padding-top: 24px; margin-top: 24px; color: rgba(255,255,255,.42); font-size: 10px; letter-spacing: .08em; }\n\ndialog { width: min(680px, calc(100% - 32px)); border: 0; padding: clamp(30px, 5vw, 58px); color: var(--ink); box-shadow: 0 30px 100px rgba(0,20,35,.32); }\ndialog::backdrop { background: rgba(3,30,47,.72); backdrop-filter: blur(6px); }\n.dialog-close { position: absolute; right: 18px; top: 14px; border: 0; background: none; color: var(--ink); font-size: 30px; font-weight: 200; cursor: pointer; }\n.dialog-heading h2, .legal-dialog h2 { font-size: clamp(42px, 7vw, 66px); margin-bottom: 20px; }\n.dialog-heading > p:last-child, .legal-dialog > p:last-child { color: var(--muted); }\nform { display: grid; gap: 18px; margin-top: 32px; }\nlabel { display: grid; gap: 7px; font-size: 10px; letter-spacing: .1em; text-transform: uppercase; }\n.optional { color: var(--muted); font-size: 9px; font-weight: 400; letter-spacing: .08em; text-transform: none; }\ninput, textarea, select { width: 100%; border: 1px solid var(--line); border-radius: 0; background: #f7fbfc; color: var(--ink); padding: 13px 14px; font-size: 15px; letter-spacing: 0; text-transform: none; }\ntextarea { resize: vertical; }\n.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; }\n.checkbox { grid-template-columns: 18px 1fr; align-items: center; color: var(--muted); text-transform: none; letter-spacing: 0; font-size: 12px; }\n.checkbox input { width: 16px; height: 16px; }\n.form-privacy { margin: -7px 0 0 33px; color: var(--muted); font-size: 12px; }\n.inline-legal { border: 0; border-bottom: 1px solid currentColor; padding: 0; background: none; color: var(--blue); cursor: pointer; font: inherit; }\n.form-status { min-height: 24px; font-size: 12px; color: var(--blue); margin: 0; }\n.form-status.success { position: relative; min-height: 62px; padding: 18px 18px 18px 58px; border: 1px solid #9fd7c3; border-left: 5px solid #23805f; background: #eaf8f2; color: #13553f; font-size: 15px; font-weight: 700; box-shadow: 0 12px 28px rgba(23,107,82,.12); }\n.form-status.success::before { content: \"✓\"; position: absolute; left: 18px; top: 50%; width: 26px; height: 26px; display: grid; place-items: center; transform: translateY(-50%); border-radius: 50%; background: #23805f; color: white; font-size: 17px; }\n.form-status.error { color: #a33232; }\n.form-submit:disabled { cursor: wait; opacity: .65; }\n.form-trap { position: absolute !important; left: -10000px !important; width: 1px !important; height: 1px !important; overflow: hidden !important; }\n.legal-dialog { width: min(760px, calc(100% - 32px)); max-height: 88vh; overflow: auto; }\n.legal-content { display: grid; gap: 0; }\n.legal-content section { padding: 22px 0; border-top: 1px solid var(--line); }\n.legal-content h3 { margin: 0 0 9px; font-family: var(--display); font-size: 24px; font-weight: 500; line-height: 1.2; }\n.legal-content p { margin: 0 0 10px; color: var(--muted); font-size: 14px; }\n.legal-content p:last-child { margin-bottom: 0; }\n.legal-content a { color: var(--blue); }\n.legal-note { padding: 15px 17px !important; border: 1px solid #bfdae7 !important; background: var(--mist); }\n.botulinum-dialog { width: min(1040px, calc(100% - 32px)); max-height: 90vh; overflow: auto; padding: clamp(34px, 5vw, 64px); }\n.botulinum-dialog-head { max-width: 760px; padding-right: 48px; }\n.botulinum-dialog-head h2 { font-size: clamp(46px, 7vw, 78px); margin: 4px 0 14px; }\n.botulinum-dialog-head > p:last-child { color: var(--muted); max-width: 720px; }\n.botulinum-dialog-grid { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(280px, .9fr); gap: clamp(28px, 5vw, 62px); align-items: center; margin-top: 34px; }\n.botulinum-visual { margin: 0; background: var(--mist); border: 1px solid var(--line); }\n.botulinum-face-map { position: relative; overflow: hidden; background: #e5f4fb; }\n.botulinum-face-map > img { display: block; width: 100%; height: auto; }\n.face-point { position: absolute; left: var(--x); top: var(--y); width: clamp(5px, .7vw, 8px); aspect-ratio: 1; border: 1px solid white; border-radius: 50%; background: var(--area-color); box-shadow: 0 1px 4px rgba(6,35,52,.24); transform: translate(-50%, -50%); }\n.area-forehead { --area-color: #287db5; }\n.area-glabella { --area-color: #bd4f68; }\n.area-crows-feet { --area-color: #7655b6; }\n.area-brow { --area-color: #d39a29; }\n.area-bunny { --area-color: #26988d; }\n.area-lip-flip { --area-color: #df6d4c; }\n.area-gummy { --area-color: #6d9f3f; }\n.area-smoker { --area-color: #bd7422; }\n.area-mouth { --area-color: #ad4b96; }\n.area-chin { --area-color: #5267b1; }\n.area-masseter { --area-color: #345b75; }\n.botulinum-visual figcaption { padding: 12px 16px; color: var(--muted); font-size: 10px; line-height: 1.45; }\n.botulinum-area-list h3 { font-family: var(--display); font-size: clamp(27px, 3vw, 38px); font-weight: 400; margin: 7px 0 20px; }\n.botulinum-area-list ul { list-style: none; padding: 0; margin: 0; border-top: 1px solid var(--line); }\n.botulinum-area-list li { padding: 11px 0 11px 18px; border-bottom: 1px solid var(--line); color: var(--muted); font-size: 14px; position: relative; }\n.botulinum-area-list li::before { content: \"\"; width: 8px; height: 8px; border: 2px solid white; border-radius: 50%; background: var(--area-color); box-shadow: 0 0 0 1px color-mix(in srgb, var(--area-color), transparent 35%); position: absolute; left: 0; top: 15px; }\n.botulinum-dialog-note { margin: 22px 0 0; padding: 18px 20px; background: var(--mist); border-left: 3px solid var(--sky); color: var(--muted); font-size: 11px; line-height: 1.55; }\n.treatment-dialog { width: min(980px, calc(100% - 32px)); max-height: 90vh; overflow: auto; padding: clamp(34px, 5vw, 68px); }\n.treatment-dialog-head { padding-right: clamp(0px, 8vw, 90px); }\n.treatment-dialog-head h2 { font-size: clamp(48px, 7vw, 82px); margin-bottom: 8px; }\n.treatment-subtitle { color: var(--blue); font-size: 11px; letter-spacing: .15em; text-transform: uppercase; margin-bottom: 22px; }\n.treatment-intro { font-family: var(--display); font-size: clamp(20px, 2.4vw, 28px); line-height: 1.45; }\n.treatment-badge { display: inline-flex; border: 1px solid var(--line); border-radius: 99px; padding: 8px 13px; color: var(--blue); font-size: 9px; letter-spacing: .12em; text-transform: uppercase; }\n.treatment-detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0; margin-top: 42px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }\n.treatment-detail-grid article { padding: 34px 34px 34px 0; }\n.treatment-detail-grid article + article { border-left: 1px solid var(--line); padding-left: 34px; }\n.detail-number, .treatment-section-title > span { color: var(--gold); font-size: 9px; letter-spacing: .16em; }\n.treatment-detail-grid h3, .treatment-section-title h3 { font-family: var(--display); font-size: 27px; font-weight: 400; margin: 8px 0 14px; }\n.treatment-detail-grid p, .treatment-detail-grid li { color: var(--muted); font-size: 13px; }\n.treatment-detail-grid ul { list-style: none; margin: 0; padding: 0; }\n.treatment-detail-grid li { padding: 7px 0 7px 14px; border-bottom: 1px solid var(--line); position: relative; }\n.treatment-detail-grid li::before { content: \"\"; width: 4px; height: 4px; background: var(--sky); border-radius: 50%; position: absolute; left: 0; top: 16px; }\n.treatment-process, .treatment-areas { padding-top: 36px; }\n.treatment-section-title { display: flex; align-items: baseline; gap: 16px; }\n.treatment-process ol { display: grid; grid-template-columns: repeat(4, 1fr); list-style: none; padding: 0; margin: 10px 0 0; counter-reset: treatment-step; }\n.treatment-process li { min-height: 126px; padding: 20px 18px; border: 1px solid var(--line); border-right: 0; counter-increment: treatment-step; display: grid; align-content: start; gap: 5px; }\n.treatment-process li:last-child { border-right: 1px solid var(--line); }\n.treatment-process li::before { content: \"0\" counter(treatment-step); color: var(--gold); font-size: 9px; letter-spacing: .14em; }\n.treatment-process li strong { font-family: var(--display); font-size: 18px; font-weight: 400; }\n.treatment-process li span { color: var(--muted); font-size: 11px; line-height: 1.4; }\n.area-tags { display: flex; flex-wrap: wrap; gap: 8px; }\n.area-tags span { border: 1px solid var(--line); padding: 9px 13px; border-radius: 99px; color: var(--muted); font-size: 10px; letter-spacing: .08em; text-transform: uppercase; }\n.treatment-caution { margin-top: 38px; padding: 24px 26px; background: var(--mist); border-left: 3px solid var(--sky); }\n.treatment-caution strong { font-family: var(--display); font-size: 20px; font-weight: 400; }\n.treatment-caution p { color: var(--muted); font-size: 12px; margin: 7px 0 0; }\n.treatment-dialog-footer { display: flex; justify-content: space-between; align-items: center; gap: 24px; margin-top: 32px; }\n.treatment-dialog-footer p { color: var(--muted); font-size: 11px; max-width: 520px; margin: 0; }\n\n.reveal { opacity: 0; transform: translateY(22px); transition: opacity .65s ease, transform .65s ease; }\n.reveal.visible { opacity: 1; transform: none; }\n\n@media (max-width: 960px) {\n  .site-header { height: 76px; }\n  .menu-toggle { display: block; z-index: 3; }\n  .navigation { display: none; position: absolute; top: 76px; left: 0; right: 0; padding: 28px; background: var(--deep); flex-direction: column; align-items: stretch; gap: 20px; }\n  .navigation.open { display: flex; }\n  .navigation > a { font-size: 15px; }\n  .hero-content { margin-left: 0; padding-left: 7vw; padding-right: 7vw; }\n  .hero-credential { right: 7vw; }\n  .expertise { grid-template-columns: 1fr .7fr; gap: 60px; }\n  .section-heading { grid-template-columns: 1fr; }\n  .service-card { padding-left: 24px; padding-right: 24px; }\n  .prices-heading { grid-template-columns: 1fr; }\n  .guide-intro { grid-template-columns: 1fr 1fr; }\n  .guide-intro .section-index { grid-column: 1 / -1; }\n  .guide-panel { grid-template-columns: .85fr 1.15fr; }\n  .result-footer { align-items: stretch; flex-direction: column; }\n  .result-footer .button { align-self: flex-start; }\n}\n\n@media (max-width: 720px) {\n  .site-header { padding: 0 20px; }\n  .brand-name { font-size: 20px; }\n  .hero { min-height: 820px; }\n  .hero-media { background-position: 63% center; }\n  .hero-shade { background: linear-gradient(90deg, rgba(3,33,52,.83), rgba(3,33,52,.3)), linear-gradient(0deg, rgba(3,33,52,.68), transparent 55%); }\n  .hero-content { min-height: 820px; justify-content: flex-end; padding: 130px 22px 160px; }\n  h1 { font-size: clamp(54px, 18vw, 78px); }\n  .hero-copy { font-size: 16px; }\n  .hero-actions { align-items: stretch; flex-direction: column; gap: 9px; }\n  .hero-actions .button { align-self: flex-start; }\n  .text-link { align-self: flex-start; }\n  .hero-credential { left: 22px; right: 22px; bottom: 32px; }\n  .hero-credential .credential-line { width: 30px; }\n  .hero-credential div:last-child { text-align: left; }\n  .hero-credential span { font-size: 8px; }\n  .section-shell, .services-inner, .prices-shell, .guide-shell { width: calc(100% - 40px); }\n  .expertise { grid-template-columns: 1fr; }\n  .care-path { grid-template-columns: 1fr 1fr; }\n  .care-path > div { border-bottom: 1px solid var(--line); }\n  .care-path > div:nth-child(2) { border-right: 0; }\n  .care-path > div:nth-child(3), .care-path > div:nth-child(4) { border-bottom: 0; }\n  h2 { font-size: clamp(46px, 14vw, 65px); }\n  .expertise-image { width: calc(100% - 14px); }\n  .section-heading { gap: 25px; margin-bottom: 44px; }\n  .service-grid { grid-template-columns: 1fr; }\n  .service-card { min-height: auto; padding: 34px 24px 40px; border-right: 0; border-bottom: 1px solid rgba(255,255,255,.17); }\n  .service-card:last-child { border-bottom: 0; }\n  .service-icon { margin: 26px 0 22px; }\n  .card-link { margin-top: 18px; }\n  .medical-note { text-align: left; }\n  .prices-heading { gap: 24px; margin-bottom: 42px; }\n  .price-groups { grid-template-columns: 1fr; }\n  .price-group { padding: 30px 22px; }\n  .price-group + .price-group { border-left: 0; border-top: 1px solid var(--line); }\n  .price-list > div { min-height: 70px; }\n  .price-list dt { font-size: 14px; }\n  .price-note { align-items: flex-start; flex-direction: column; }\n  .guide-intro { grid-template-columns: 1fr; }\n  .guide-intro .section-index { grid-column: auto; }\n  .guide-panel { grid-template-columns: 1fr; }\n  .concern-list { display: flex; overflow-x: auto; padding: 0; scroll-snap-type: x mandatory; }\n  .concern { flex: 0 0 74%; min-height: 72px; border-bottom: 0; border-right: 1px solid rgba(12,49,73,.12); padding: 0 22px; font-size: 18px; scroll-snap-align: start; }\n  .concern:hover, .concern.active { padding-left: 22px; }\n  .guide-result { min-height: 550px; padding: 38px 24px; }\n  .guide-result h3 { font-size: 48px; }\n  .contact-strip { flex-direction: column; align-items: flex-start; }\n  .site-footer { grid-template-columns: 1fr; }\n  .site-footer small { grid-column: auto; }\n  .form-row { grid-template-columns: 1fr; }\n  .treatment-links { grid-template-columns: 1fr; }\n  .botulinum-dialog-grid { grid-template-columns: 1fr; }\n  .botulinum-dialog-head { padding-right: 28px; }\n  .botulinum-face-map > img { max-height: none; }\n  .treatment-detail-grid { grid-template-columns: 1fr; }\n  .treatment-detail-grid article { padding: 28px 0; }\n  .treatment-detail-grid article + article { border-left: 0; border-top: 1px solid var(--line); padding-left: 0; }\n  .treatment-process ol { grid-template-columns: 1fr 1fr; }\n  .treatment-process li:nth-child(2) { border-right: 1px solid var(--line); }\n  .treatment-process li:nth-child(3), .treatment-process li:nth-child(4) { border-top: 0; }\n  .treatment-dialog-footer { align-items: stretch; flex-direction: column; }\n  .treatment-dialog-footer .button { align-self: flex-start; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  html { scroll-behavior: auto; }\n  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; }\n  .reveal { opacity: 1; transform: none; }\n}\n</style>\n</head>\n<body>\n  <a class=\"skip-link\" href=\"#inhalt\">Zum Inhalt</a>\n\n  <header class=\"site-header\" id=\"start\">\n    <a class=\"brand\" href=\"#start\" aria-label=\"Zur Startseite\">\n      <span class=\"brand-mark\" aria-hidden=\"true\">RT</span>\n      <span class=\"brand-text\">\n        <span class=\"brand-name\">Robert Tobis</span>\n        <span class=\"brand-caption\">Ästhetische Medizin</span>\n      </span>\n    </a>\n    <button class=\"menu-toggle\" type=\"button\" aria-expanded=\"false\" aria-controls=\"navigation\">\n      <span></span><span></span><span></span>\n      <span class=\"sr-only\">Menü öffnen</span>\n    </button>\n    <nav id=\"navigation\" class=\"navigation\" aria-label=\"Hauptnavigation\">\n      <a href=\"#profil\">Profil</a>\n      <a href=\"#leistungen\">Leistungen</a>\n      <a href=\"#preise\">Preise</a>\n      <a href=\"#orientierung\">Orientierung</a>\n      <button class=\"button button-small js-open-contact\" type=\"button\">Beratung anfragen</button>\n    </nav>\n  </header>\n\n  <main id=\"inhalt\">\n    <section class=\"hero\" aria-labelledby=\"hero-title\">\n      <div class=\"hero-media\" role=\"img\" aria-label=\"Natürlich hellblonde Frau in einer hellen medizinischen Umgebung\"></div>\n      <div class=\"hero-shade\"></div>\n      <div class=\"hero-content\">\n        <p class=\"eyebrow\">Blutbehandlung · Botox / Botulinumtoxin · Hyaluronsäure</p>\n        <h1 id=\"hero-title\">Natürlichkeit<br><em>mit Präzision.</em></h1>\n        <p class=\"hero-copy\">Die Therapie wird individuell ausgewählt und ärztlich geplant – mit Eigenblut (PRP/i-PRF), Botulinumtoxin oder Hyaluronsäure, chirurgischer Erfahrung und einem klaren Blick für harmonische Proportionen.</p>\n        <div class=\"hero-actions\">\n          <button class=\"button js-open-contact\" type=\"button\">Beratung anfragen <span aria-hidden=\"true\">↗</span></button>\n          <a class=\"text-link\" href=\"#orientierung\">Behandlung erkunden <span aria-hidden=\"true\">↓</span></a>\n        </div>\n      </div>\n      <div class=\"hero-credential\" id=\"profil\">\n        <div class=\"credential-line\"></div>\n        <div>\n          <strong>Robert Tobis</strong>\n          <span>Facharzt für Chirurgie · Facharzt für Allgemeinmedizin</span>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"expertise section-shell\" aria-labelledby=\"expertise-title\">\n      <div class=\"expertise-copy reveal\">\n        <p class=\"section-index\">01 · Ärztliches Profil</p>\n        <h2 id=\"expertise-title\">Erfahrung, die<br><em>Sicherheit gibt.</em></h2>\n        <p class=\"lead\">Mehr als 30 Jahre klinische und chirurgische Erfahrung prägen einen ruhigen, präzisen und verantwortungsvollen Behandlungsansatz.</p>\n        <p>Viele Jahre Tätigkeit als Oberarzt und leitender Oberarzt in der Allgemeinchirurgie, die Facharztausbildung in Allgemeinmedizin und ästhetische Behandlungen seit 2020 verbinden sich zu einem ganzheitlichen Blick auf Anatomie, Sicherheit und natürliche Proportionen.</p>\n        <p>Im Mittelpunkt steht kein vorgegebenes Schönheitsideal, sondern ein Ergebnis, das zu Gesicht, Ausdruck und individueller Situation passt.</p>\n        <div class=\"principles\" aria-label=\"Behandlungsgrundsätze\">\n          <span>Ärztliche Aufklärung</span>\n          <span>Individueller Plan</span>\n          <span>Zurückhaltende Ästhetik</span>\n        </div>\n        <div class=\"care-path\" aria-label=\"Von der Beratung zur Behandlung\">\n          <div><b>01</b><strong>Gespräch</strong><span>Wünsche & Vorgeschichte</span></div>\n          <div><b>02</b><strong>Analyse</strong><span>Anatomie, Mimik & Gewebe</span></div>\n          <div><b>03</b><strong>Planung</strong><span>Methode & realistische Ziele</span></div>\n          <div><b>04</b><strong>Nachsorge</strong><span>Hinweise & Kontrolle</span></div>\n        </div>\n      </div>\n      <figure class=\"expertise-image reveal\">\n        <img src=\"/assets/portrait-premium.webp\" alt=\"Natürliches Porträt einer hellblonden Frau in medizinischer Umgebung\" width=\"1024\" height=\"1365\" loading=\"lazy\">\n        <figcaption><span>Medizinische Ästhetik</span><span>Diskret · präzise · persönlich</span></figcaption>\n      </figure>\n    </section>\n\n    <section class=\"services\" id=\"leistungen\" aria-labelledby=\"services-title\">\n      <div class=\"section-shell services-inner\">\n        <div class=\"section-heading reveal\">\n          <div>\n            <p class=\"section-index light\">02 · Behandlungsspektrum</p>\n            <h2 id=\"services-title\">Gezielt behandeln.<br><em>Natürlich wirken.</em></h2>\n          </div>\n          <p>Jede Behandlung beginnt mit einer persönlichen ärztlichen Beratung. Eignung, Vorgehen, mögliche Risiken und realistische Erwartungen werden individuell besprochen.</p>\n        </div>\n\n        <div class=\"service-grid\">\n          <article class=\"service-card reveal\">\n            <div class=\"service-number\">01</div>\n            <div class=\"service-icon\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 64 64\"><path d=\"M18 43c5-3 8-9 8-16 0-7 3-12 8-12 6 0 11 7 11 16 0 10-6 18-14 18-5 0-9-2-13-6Z\"/><path d=\"M27 27c4 2 9 2 15 0M31 36c3 1 6 1 9 0\"/></svg>\n            </div>\n            <h3>Botulinumtoxin</h3>\n            <p>Für ausgewählte mimische Bereiche und funktionelle Indikationen – dosiert nach Anatomie, Muskelaktivität und gewünschtem Ausdruck.</p>\n            <ul>\n              <li>Stirn, Zornesfalte & Krähenfüße</li>\n              <li>Augenbrauenanhebung & Bunny Lines</li>\n              <li>Lip Flip, Gummy Smile & Raucherfältchen</li>\n              <li>Mundwinkel, Kinnfältchen & Masseterbehandlung</li>\n              <li>Hyperhidrose & Migräne*</li>\n            </ul>\n            <button class=\"botox-map-link js-open-botulinum\" type=\"button\" aria-haspopup=\"dialog\" aria-controls=\"botulinum-dialog\">\n              <span class=\"map-thumb\" aria-hidden=\"true\"><img src=\"/assets/botulinum-portrait.webp\" alt=\"\"></span>\n              <span><strong>Behandlungsareale</strong><small>Übersicht im Fenster öffnen</small></span>\n              <b aria-hidden=\"true\">↗</b>\n            </button>\n            <button class=\"card-link js-select-service\" data-service=\"botulinum\" type=\"button\">Einsatzbereiche ansehen <span>→</span></button>\n          </article>\n\n          <article class=\"service-card featured reveal\">\n            <div class=\"service-number\">02</div>\n            <div class=\"service-icon\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 64 64\"><path d=\"M14 35c8-2 12-8 18-8s10 6 18 8c-4 9-10 14-18 14S18 44 14 35Z\"/><path d=\"M17 35c8 1 22 1 30 0M32 27c0-6 3-10 8-13\"/></svg>\n            </div>\n            <h3>Hyaluronsäure</h3>\n            <p>Zur behutsamen Modellierung, zum Ausgleich ausgewählter Konturen und zur Betonung natürlicher Proportionen.</p>\n            <ul>\n              <li>Gesichtsmodellierung</li>\n              <li>Faltenbehandlung</li>\n              <li>Lippenkontur & Lippenvolumen</li>\n              <li>Individueller, stufenweiser Aufbau</li>\n            </ul>\n            <button class=\"card-link js-select-service\" data-service=\"hyaluron\" type=\"button\">Einsatzbereiche ansehen <span>→</span></button>\n          </article>\n\n          <article class=\"service-card reveal\">\n            <div class=\"service-number\">03</div>\n            <div class=\"service-icon\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 64 64\"><path d=\"M32 11c8 11 15 18 15 27a15 15 0 0 1-30 0c0-9 7-16 15-27Z\"/><path d=\"M24 39c2 5 6 7 11 7\"/></svg>\n            </div>\n            <h3>PRP · i-PRF · Exosomen</h3>\n            <p>Eigenblutbasierte Verfahren mit plättchenreichem Plasma, Fibrin oder körpereigenen Exosomen (EVs) – ärztlich geplant zur schrittweisen Unterstützung der Hautqualität.</p>\n            <ul>\n              <li>PRP · plättchenreiches Plasma</li>\n              <li>i-PRF · injizierbares plättchenreiches Fibrin</li>\n              <li>Autologe exosomale PRF-Therapie</li>\n              <li>Gesicht, Augenregion, Hals & Dekolleté</li>\n              <li>Handrücken & Kopfhaut</li>\n              <li>Körpereigenes Ausgangsmaterial</li>\n            </ul>\n            <div class=\"treatment-links\" aria-label=\"Ausführliche Informationen\">\n              <button class=\"treatment-link js-open-treatment\" data-treatment=\"iprf\" type=\"button\"><span>i-PRF</span><small>Mehr erfahren</small><b aria-hidden=\"true\">↗</b></button>\n              <button class=\"treatment-link js-open-treatment\" data-treatment=\"exosomes\" type=\"button\"><span>Exosomen</span><small>Mehr erfahren</small><b aria-hidden=\"true\">↗</b></button>\n            </div>\n            <button class=\"card-link js-select-service\" data-service=\"prp\" type=\"button\">Einsatzbereiche ansehen <span>→</span></button>\n          </article>\n        </div>\n        <p class=\"medical-note\">* Nur nach individueller ärztlicher Indikationsprüfung. Einzelne Anwendungen können – abhängig von Präparat und Region – außerhalb der zugelassenen Indikation erfolgen und erfordern eine gesonderte Aufklärung. Exosomale PRF ist kein klassischer Filler; Ergebnisse sind individuell und nicht garantiert. Die Darstellung ersetzt keine Untersuchung oder Diagnose.</p>\n      </div>\n    </section>\n\n    <section class=\"prices\" id=\"preise\" aria-labelledby=\"prices-title\">\n      <div class=\"section-shell prices-shell\">\n        <div class=\"prices-heading reveal\">\n          <div>\n            <p class=\"section-index\">03 · Preise</p>\n            <h2 id=\"prices-title\">Klare Orientierung.<br><em>Persönlich geplant.</em></h2>\n          </div>\n          <p>Transparente Behandlungspreise geben Ihnen vorab einen verlässlichen Überblick. Eignung und Behandlungsumfang werden immer persönlich ärztlich besprochen.</p>\n        </div>\n\n        <div class=\"price-groups reveal\">\n          <article class=\"price-group\">\n            <div class=\"price-group-head\"><span>01</span><h3>Botulinumtoxin</h3></div>\n            <dl class=\"price-list\">\n              <div><dt>Eine Region</dt><dd>90&nbsp;€</dd></div>\n              <div><dt>Krähenfüße</dt><dd>130&nbsp;€</dd></div>\n              <div><dt>Drei Regionen</dt><dd class=\"price-on-request\">nach Beratung</dd></div>\n              <div><dt>Masseterbehandlung</dt><dd>210&nbsp;€</dd></div>\n            </dl>\n          </article>\n\n          <article class=\"price-group price-group-accent\">\n            <div class=\"price-group-head\"><span>02</span><h3>Weitere Behandlungen</h3></div>\n            <dl class=\"price-list\">\n              <div><dt>Hyaluronsäure <small>1 ml</small></dt><dd>200&nbsp;€</dd></div>\n              <div><dt>PRP / PRF <small>eine Behandlung</small></dt><dd>250&nbsp;€</dd></div>\n              <div><dt>Autologe Exosomen <small>eine Behandlung</small></dt><dd>400&nbsp;€</dd></div>\n            </dl>\n          </article>\n        </div>\n\n        <div class=\"price-note reveal\">\n          <p>Die genannten Beträge sind Endpreise für den jeweils beschriebenen Behandlungsumfang. Die Abrechnung erfolgt nach GOÄ. Vor der Behandlung werden Vorgehen und Kosten transparent erläutert.</p>\n          <button class=\"button js-open-contact\" type=\"button\">Beratung anfragen <span aria-hidden=\"true\">↗</span></button>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"guide\" id=\"orientierung\" aria-labelledby=\"guide-title\">\n      <div class=\"section-shell guide-shell\">\n        <div class=\"guide-intro reveal\">\n          <p class=\"section-index\">04 · Behandlungsorientierung</p>\n          <h2 id=\"guide-title\">Was möchten Sie<br><em>näher erkunden?</em></h2>\n          <p>Wählen Sie ein Anliegen. Sie erhalten eine unverbindliche Übersicht möglicher Leistungsbereiche – ohne Diagnose und ohne Heilversprechen.</p>\n        </div>\n\n        <div class=\"guide-panel reveal\" data-guide>\n          <div class=\"concern-list\" role=\"list\" aria-label=\"Anliegen auswählen\">\n            <button class=\"concern active\" type=\"button\" data-concern=\"mimik\" aria-pressed=\"true\"><span>01</span>Mimiklinien</button>\n            <button class=\"concern\" type=\"button\" data-concern=\"kontur\" aria-pressed=\"false\"><span>02</span>Kontur & Volumen</button>\n            <button class=\"concern\" type=\"button\" data-concern=\"lippen\" aria-pressed=\"false\"><span>03</span>Lippen & Mundregion</button>\n            <button class=\"concern\" type=\"button\" data-concern=\"haut\" aria-pressed=\"false\"><span>04</span>Haut & Haare</button>\n            <button class=\"concern\" type=\"button\" data-concern=\"funktion\" aria-pressed=\"false\"><span>05</span>Funktionelle Anliegen</button>\n          </div>\n          <div class=\"guide-result\" aria-live=\"polite\">\n            <div class=\"result-kicker\">Möglicher Leistungsbereich</div>\n            <h3 data-result-title>Botulinumtoxin</h3>\n            <p data-result-copy>Kann für ausgewählte mimische Bereiche wie Stirn, Zornesfalte oder Krähenfüße in Betracht kommen. Ziel und Dosierung werden an Muskelaktivität und gewünschte Natürlichkeit angepasst.</p>\n            <div class=\"result-tags\" data-result-tags><span>Stirn</span><span>Zornesfalte</span><span>Krähenfüße</span></div>\n            <div class=\"result-footer\">\n              <p>Ob eine Behandlung medizinisch sinnvoll und für Sie geeignet ist, klärt ausschließlich das persönliche ärztliche Gespräch.</p>\n              <button class=\"button js-open-contact\" type=\"button\">Beratung anfragen <span aria-hidden=\"true\">↗</span></button>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"contact-strip reveal\" id=\"kontakt\">\n          <div>\n            <span>Persönlich beraten lassen</span>\n            <h3>Der nächste Schritt beginnt mit einem Gespräch.</h3>\n          </div>\n          <button class=\"button button-light js-open-contact\" type=\"button\">Unverbindlich anfragen <span aria-hidden=\"true\">↗</span></button>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <footer class=\"site-footer\">\n    <div class=\"footer-brand\">\n      <span class=\"brand-mark light-mark\" aria-hidden=\"true\">RT</span>\n      <div><strong>Robert Tobis</strong><span>Ästhetische Medizin</span></div>\n    </div>\n    <p>Facharzt für Chirurgie · Facharzt für Allgemeinmedizin</p>\n    <div class=\"footer-links\">\n      <button type=\"button\" class=\"js-legal\" data-legal=\"Impressum\">Impressum</button>\n      <button type=\"button\" class=\"js-legal\" data-legal=\"Datenschutz\">Datenschutz</button>\n    </div>\n    <small>© <span id=\"year\"></span> Robert Tobis · Ästhetische Medizin in Zwickau</small>\n  </footer>\n\n  <dialog class=\"contact-dialog\" id=\"contact-dialog\" aria-labelledby=\"contact-title\">\n    <button class=\"dialog-close\" type=\"button\" aria-label=\"Dialog schließen\">×</button>\n    <div class=\"dialog-heading\">\n      <p class=\"section-index\">Persönliche Beratung</p>\n      <h2 id=\"contact-title\">Ihre Anfrage</h2>\n      <p>Teilen Sie kurz mit, wofür Sie sich interessieren. Bitte übermitteln Sie keine medizinischen Befunde oder sensiblen Gesundheitsdaten.</p>\n    </div>\n    <form id=\"contact-form\">\n      <input class=\"form-trap\" name=\"website\" type=\"text\" tabindex=\"-1\" autocomplete=\"off\" aria-hidden=\"true\">\n      <input name=\"startedAt\" type=\"hidden\" value=\"\">\n      <label>Name<input name=\"name\" autocomplete=\"name\" required maxlength=\"120\" placeholder=\"Vor- und Nachname\"></label>\n      <div class=\"form-row\">\n        <label>E-Mail<input name=\"email\" type=\"email\" autocomplete=\"email\" required maxlength=\"200\" placeholder=\"name@beispiel.de\"></label>\n        <label>Telefon <span class=\"optional\">optional</span><input name=\"phone\" type=\"tel\" autocomplete=\"tel\" maxlength=\"40\" placeholder=\"Für einen Rückruf\"></label>\n      </div>\n      <label>Interesse<select name=\"interest\"><option>Allgemeine Beratung</option><option>Botulinumtoxin</option><option>Hyaluronsäure</option><option>PRP / PRF / autologe Exosomen</option></select></label>\n      <label>Nachricht<textarea name=\"message\" rows=\"4\" maxlength=\"2000\" placeholder=\"Was möchten Sie besprechen?\"></textarea></label>\n      <label class=\"checkbox\"><input name=\"privacy\" type=\"checkbox\" required><span>Ich bin mit der Verarbeitung meiner Angaben zur Beantwortung meiner Anfrage einverstanden. Bitte keine Befunde oder sensiblen Gesundheitsdaten senden.</span></label>\n      <p class=\"form-privacy\">Weitere Informationen finden Sie in der <button type=\"button\" class=\"inline-legal js-legal\" data-legal=\"Datenschutz\">Datenschutzerklärung</button>.</p>\n      <button class=\"button form-submit\" type=\"submit\">Anfrage senden <span aria-hidden=\"true\">→</span></button>\n      <p class=\"form-status\" role=\"status\" aria-live=\"polite\" tabindex=\"-1\"></p>\n    </form>\n  </dialog>\n\n  <dialog class=\"legal-dialog\" id=\"legal-dialog\" aria-labelledby=\"legal-title\">\n    <button class=\"dialog-close\" type=\"button\" aria-label=\"Dialog schließen\">×</button>\n    <p class=\"section-index\">Rechtlicher Hinweis</p>\n    <h2 id=\"legal-title\">Impressum</h2>\n    <div class=\"legal-content\" id=\"legal-content\"></div>\n  </dialog>\n\n  <dialog class=\"botulinum-dialog\" id=\"botulinum-dialog\" aria-labelledby=\"botulinum-dialog-title\">\n    <button class=\"dialog-close\" type=\"button\" aria-label=\"Detailansicht schließen\">×</button>\n    <div class=\"botulinum-dialog-head\">\n      <p class=\"section-index\">Botulinumtoxin</p>\n      <h2 id=\"botulinum-dialog-title\">Behandlungsareale</h2>\n      <p>Eine kompakte Orientierung zu häufig nachgefragten Bereichen. Die konkrete Auswahl und Dosierung erfolgen immer individuell nach Anatomie, Mimik und ärztlicher Untersuchung.</p>\n    </div>\n    <div class=\"botulinum-dialog-grid\">\n      <figure class=\"botulinum-visual\">\n        <div class=\"botulinum-face-map\" role=\"img\" aria-label=\"Frontalansicht eines Gesichts mit farblich nach Behandlungsbereich gruppierten Orientierungspunkten\">\n          <img src=\"/assets/botulinum-portrait.webp\" alt=\"\">\n          <span class=\"face-point area-forehead\" style=\"--x:35%;--y:22%\"></span>\n          <span class=\"face-point area-forehead\" style=\"--x:42.5%;--y:22%\"></span>\n          <span class=\"face-point area-forehead\" style=\"--x:55.2%;--y:22%\"></span>\n          <span class=\"face-point area-forehead\" style=\"--x:62.6%;--y:22%\"></span>\n          <span class=\"face-point area-glabella\" style=\"--x:44.6%;--y:30%\"></span>\n          <span class=\"face-point area-glabella\" style=\"--x:53.4%;--y:30%\"></span>\n          <span class=\"face-point area-glabella\" style=\"--x:48.9%;--y:32.6%\"></span>\n          <span class=\"face-point area-glabella\" style=\"--x:48.9%;--y:35.2%\"></span>\n          <span class=\"face-point area-crows-feet\" style=\"--x:28.5%;--y:36.4%\"></span>\n          <span class=\"face-point area-crows-feet\" style=\"--x:29.2%;--y:38.7%\"></span>\n          <span class=\"face-point area-crows-feet\" style=\"--x:28.3%;--y:39.8%\"></span>\n          <span class=\"face-point area-crows-feet\" style=\"--x:68.5%;--y:36.4%\"></span>\n          <span class=\"face-point area-crows-feet\" style=\"--x:68%;--y:38.7%\"></span>\n          <span class=\"face-point area-crows-feet\" style=\"--x:69.2%;--y:39.8%\"></span>\n          <span class=\"face-point area-brow\" style=\"--x:30.3%;--y:30%\"></span>\n          <span class=\"face-point area-brow\" style=\"--x:67.3%;--y:30%\"></span>\n          <span class=\"face-point area-bunny\" style=\"--x:44.6%;--y:43.5%\"></span>\n          <span class=\"face-point area-bunny\" style=\"--x:52.9%;--y:43.5%\"></span>\n          <span class=\"face-point area-gummy\" style=\"--x:42.6%;--y:48.5%\"></span>\n          <span class=\"face-point area-gummy\" style=\"--x:55%;--y:48.5%\"></span>\n          <span class=\"face-point area-smoker\" style=\"--x:43.7%;--y:53.4%\"></span>\n          <span class=\"face-point area-smoker\" style=\"--x:54%;--y:53.4%\"></span>\n          <span class=\"face-point area-lip-flip\" style=\"--x:47%;--y:53.8%\"></span>\n          <span class=\"face-point area-lip-flip\" style=\"--x:51%;--y:53.8%\"></span>\n          <span class=\"face-point area-mouth\" style=\"--x:38.1%;--y:56.3%\"></span>\n          <span class=\"face-point area-mouth\" style=\"--x:59.3%;--y:56.3%\"></span>\n          <span class=\"face-point area-chin\" style=\"--x:48.8%;--y:64.2%\"></span>\n          <span class=\"face-point area-masseter\" style=\"--x:29%;--y:56.2%\"></span>\n          <span class=\"face-point area-masseter\" style=\"--x:68.5%;--y:56.2%\"></span>\n        </div>\n        <figcaption>Farben und Punkte dienen der Orientierung – keine Darstellung eines festen Injektionsschemas.</figcaption>\n      </figure>\n      <div class=\"botulinum-area-list\">\n        <p class=\"section-index\">Typische Bereiche</p>\n        <h3>Mimik, Ausdruck und Kontur</h3>\n        <ul>\n          <li class=\"area-forehead\">Stirnfalten</li>\n          <li class=\"area-glabella\">Zornesfalte</li>\n          <li class=\"area-crows-feet\">Krähenfüße</li>\n          <li class=\"area-brow\">Augenbrauenanhebung</li>\n          <li class=\"area-bunny\">Bunny Lines</li>\n          <li class=\"area-lip-flip\">Lip Flip</li>\n          <li class=\"area-gummy\">Gummy Smile</li>\n          <li class=\"area-smoker\">Raucherfältchen</li>\n          <li class=\"area-mouth\">Mundwinkel</li>\n          <li class=\"area-chin\">Kinnfältchen</li>\n          <li class=\"area-masseter\">Masseterbehandlung / Face Slimming</li>\n        </ul>\n        <p class=\"botulinum-dialog-note\">Weitere medizinische Anwendungen wie Hyperhidrose- oder Migränebehandlung werden ausschließlich nach gesonderter ärztlicher Indikationsprüfung besprochen.</p>\n      </div>\n    </div>\n  </dialog>\n\n  <dialog class=\"treatment-dialog\" id=\"treatment-dialog\" aria-labelledby=\"treatment-title\">\n    <button class=\"dialog-close\" type=\"button\" aria-label=\"Detailansicht schließen\">×</button>\n    <div class=\"treatment-dialog-head\">\n      <p class=\"section-index\" data-treatment-kicker>Regenerative Ästhetik</p>\n      <h2 id=\"treatment-title\" data-treatment-title>i-PRF</h2>\n      <p class=\"treatment-subtitle\" data-treatment-subtitle></p>\n      <p class=\"treatment-intro\" data-treatment-intro></p>\n      <span class=\"treatment-badge\" data-treatment-badge></span>\n    </div>\n    <div class=\"treatment-detail-grid\">\n      <article>\n        <span class=\"detail-number\">01</span>\n        <h3 data-treatment-explainer-title></h3>\n        <p data-treatment-explainer></p>\n      </article>\n      <article>\n        <span class=\"detail-number\">02</span>\n        <h3>Mögliche Behandlungsziele</h3>\n        <ul data-treatment-goals></ul>\n      </article>\n    </div>\n    <div class=\"treatment-process\">\n      <div class=\"treatment-section-title\"><span>03</span><h3>Behandlung auf einen Blick</h3></div>\n      <ol data-treatment-steps></ol>\n    </div>\n    <div class=\"treatment-areas\">\n      <div class=\"treatment-section-title\"><span>04</span><h3>Behandlungsbereiche</h3></div>\n      <div class=\"area-tags\" data-treatment-areas></div>\n    </div>\n    <div class=\"treatment-caution\">\n      <strong>Wichtig zu wissen</strong>\n      <p data-treatment-safety></p>\n    </div>\n    <div class=\"treatment-dialog-footer\">\n      <p>Die Detailansicht ersetzt keine persönliche Anamnese, Untersuchung oder ärztliche Aufklärung.</p>\n      <button class=\"button js-treatment-contact\" type=\"button\">Beratung anfragen <span aria-hidden=\"true\">↗</span></button>\n    </div>\n  </dialog>\n\n  <script>const guideContent = {\n  mimik: {\n    title: \"Botulinumtoxin\",\n    copy: \"Kann für ausgewählte mimische Bereiche wie Stirn, Zornesfalte oder Krähenfüße in Betracht kommen. Ziel und Dosierung werden an Muskelaktivität und gewünschte Natürlichkeit angepasst.\",\n    tags: [\"Stirn\", \"Zornesfalte\", \"Krähenfüße\"]\n  },\n  kontur: {\n    title: \"Hyaluronsäure\",\n    copy: \"Kann zur behutsamen Modellierung ausgewählter Gesichtskonturen oder zum Ausgleich von Volumen eingesetzt werden. Proportion, Gewebestruktur und ein stufenweises Vorgehen stehen im Vordergrund.\",\n    tags: [\"Gesichtsmodellierung\", \"Konturen\", \"Volumen\"]\n  },\n  lippen: {\n    title: \"Lippen & Mundregion\",\n    copy: \"Je nach Ausgangssituation können Hyaluronsäure oder ausgewählte Botulinumtoxin-Anwendungen besprochen werden – etwa für Kontur, Volumen, Lip Flip, Gummy Smile, Raucherfältchen oder Mundwinkel.\",\n    tags: [\"Hyaluronsäure\", \"Lip Flip\", \"Mundregion\"]\n  },\n  haut: {\n    title: \"PRP · PRF · Exosomen\",\n    copy: \"Je nach Befund können PRP, PRF oder eine autologe exosomale PRF-Therapie mit körpereigenen EVs aus Eigenblut für Haut oder Kopfhaut besprochen werden. Im Mittelpunkt steht die schrittweise Unterstützung der Hautqualität – nicht sofortiges Volumen.\",\n    tags: [\"PRP\", \"PRF\", \"Autologe Exosomen\"]\n  },\n  funktion: {\n    title: \"Ärztliche Indikationsprüfung\",\n    copy: \"Bei starkem Schwitzen, Beschwerden im Bereich des Masseters oder ausgewählten Migräne-Konstellationen kann Botulinumtoxin medizinisch geprüft werden. Voraussetzung ist stets eine individuelle Anamnese und ärztliche Beurteilung.\",\n    tags: [\"Hyperhidrose\", \"Masseter\", \"Migräne\"]\n  }\n};\n\nconst treatmentContent = {\n  iprf: {\n    kicker: \"Regenerative Ästhetik · Eigenblut\",\n    title: \"i-PRF\",\n    subtitle: \"Injizierbares plättchenreiches Fibrin\",\n    intro: \"Ein körpereigenes Regenerationskonzept: Aus einer kleinen Menge Eigenblut wird eine plättchen- und fibrinreiche Fraktion gewonnen und unmittelbar in ausgewählte Areale eingebracht.\",\n    badge: \"Natürlich statt sofortigem Volumen\",\n    explainerTitle: \"Was ist i-PRF?\",\n    explainer: \"i-PRF enthält Blutplättchen, ein feines Fibrinnetz und Signalproteine. Je nach Aufbereitung können geringe Mengen CD34-positiver hämatopoetischer Stamm- und Vorläuferzellen enthalten sein; deren klinische Bedeutung wird weiter erforscht. i-PRF ist kein Hyaluron-Filler.\",\n    goals: [\n      \"Umfassende Hautregeneration\",\n      \"Unterstützung von Hautstruktur, Elastizität und Festigkeit\",\n      \"Feine Linien können im Verlauf weicher erscheinen\",\n      \"Unterstützung der Mikroumgebung vitaler Haarfollikel\",\n      \"Unterstützung von kräftigerem Haar und einer höheren Haardichte\",\n      \"Schrittweise Entwicklung statt sofortigem Volumeneffekt\"\n    ],\n    steps: [\n      [\"Blutentnahme\", \"Eine kleine Menge Eigenblut wird entnommen.\"],\n      [\"Aufbereitung\", \"Schonende Gewinnung der plättchen- und fibrinreichen Fraktion.\"],\n      [\"Injektion\", \"Gezielte Anwendung in ausgewählten Hautarealen oder an der Kopfhaut.\"],\n      [\"Entwicklung\", \"Veränderungen entstehen schrittweise und sind individuell.\"]\n    ],\n    areas: [\"Gesicht\", \"Augenregion\", \"Hals\", \"Dekolleté\", \"Handrücken\", \"Kopfhaut\"],\n    safety: \"Vorübergehend können Rötung, Schwellung, Druckempfindlichkeit oder kleine Hämatome auftreten. Wie bei jeder Injektion sind selten weitere Komplikationen möglich. Eignung, Risiken, Alternativen und realistische Erwartungen werden persönlich ärztlich geklärt.\"\n  },\n  exosomes: {\n    kicker: \"Regenerative Ästhetik · Eigenblut\",\n    title: \"Autologe Exosomen\",\n    subtitle: \"Exosomale plättchenreiche Fibrintherapie\",\n    intro: \"Aus einer kleinen Menge Eigenblut wird nach einem festgelegten Praxisprotokoll ein autologes Präparat gewonnen. Es enthält körpereigene Exosomen beziehungsweise extrazelluläre Vesikel (EVs), plättchenreiches Fibrin, weitere Blutbestandteile und Signalproteine.\",\n    badge: \"Körpereigene EVs · kein Spendergewebe\",\n    explainerTitle: \"Was sind Exosomen (EVs)?\",\n    explainer: \"Exosomen sind kleine, von Zellen freigesetzte Vesikel. Sie können Proteine, Lipide und Nukleinsäuren transportieren und sind an der Kommunikation zwischen Zellen beteiligt. In Verbindung mit plättchenreichem Fibrin können sie zusätzliche zelluläre Signale bereitstellen.\",\n    goals: [\n      \"Unterstützung von Hautstruktur, Festigkeit und Elastizität\",\n      \"Feine Linien können im Verlauf weniger ausgeprägt erscheinen\",\n      \"Unterstützung natürlicher Umbau- und Reparaturprozesse\"\n    ],\n    steps: [\n      [\"Blutentnahme\", \"Eine kleine Menge Eigenblut wird entnommen.\"],\n      [\"Aufbereitung\", \"Gewinnung des autologen Präparats nach Praxisprotokoll.\"],\n      [\"Injektion\", \"Gezielte Anwendung in Haut oder Unterhaut.\"],\n      [\"Nachsorge\", \"Individuelle ärztliche Hinweise und Kontrolle.\"]\n    ],\n    areas: [\"Ausgewählte Hautareale\", \"Gesicht\", \"Haut\", \"Unterhaut\"],\n    safety: \"Vorübergehend können Rötung, Schwellung, Druckempfindlichkeit, Schmerzen, Juckreiz oder Hämatome auftreten. Das Verfahren ist kein klassischer Filler; Ergebnisse sind individuell und nicht garantiert. Anamnese und Aufklärung klären Eignung, Alternativen und persönliche Risiken.\"\n  }\n};\n\nconst menuButton = document.querySelector(\".menu-toggle\");\nconst navigation = document.querySelector(\".navigation\");\nmenuButton?.addEventListener(\"click\", () => {\n  const open = menuButton.getAttribute(\"aria-expanded\") === \"true\";\n  menuButton.setAttribute(\"aria-expanded\", String(!open));\n  navigation.classList.toggle(\"open\", !open);\n});\nnavigation?.querySelectorAll(\"a\").forEach(link => link.addEventListener(\"click\", () => {\n  navigation.classList.remove(\"open\");\n  menuButton?.setAttribute(\"aria-expanded\", \"false\");\n}));\n\nconst title = document.querySelector(\"[data-result-title]\");\nconst copy = document.querySelector(\"[data-result-copy]\");\nconst tags = document.querySelector(\"[data-result-tags]\");\nfunction setGuide(key, scroll = false) {\n  const content = guideContent[key];\n  if (!content || !title || !copy || !tags) return;\n  document.querySelectorAll(\".concern\").forEach(button => {\n    const active = button.dataset.concern === key;\n    button.classList.toggle(\"active\", active);\n    button.setAttribute(\"aria-pressed\", String(active));\n  });\n  title.textContent = content.title;\n  copy.textContent = content.copy;\n  tags.replaceChildren(...content.tags.map(tag => {\n    const span = document.createElement(\"span\");\n    span.textContent = tag;\n    return span;\n  }));\n  if (scroll) document.querySelector(\"#orientierung\")?.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n}\ndocument.querySelectorAll(\".concern\").forEach(button => button.addEventListener(\"click\", () => setGuide(button.dataset.concern)));\ndocument.querySelectorAll(\".js-select-service\").forEach(button => button.addEventListener(\"click\", () => {\n  const mapping = { botulinum: \"mimik\", hyaluron: \"kontur\", prp: \"haut\" };\n  setGuide(mapping[button.dataset.service], true);\n}));\n\nconst treatmentDialog = document.querySelector(\"#treatment-dialog\");\nfunction replaceTextList(selector, items, className) {\n  const target = treatmentDialog?.querySelector(selector);\n  if (!target) return;\n  target.replaceChildren(...items.map(item => {\n    const element = document.createElement(className === \"tag\" ? \"span\" : \"li\");\n    if (className === \"step\") {\n      const strong = document.createElement(\"strong\");\n      strong.textContent = item[0];\n      const span = document.createElement(\"span\");\n      span.textContent = item[1];\n      element.append(strong, span);\n    } else {\n      element.textContent = item;\n    }\n    return element;\n  }));\n}\nfunction openTreatment(key) {\n  const content = treatmentContent[key];\n  if (!content || !treatmentDialog) return;\n  const fields = [\"kicker\", \"title\", \"subtitle\", \"intro\", \"badge\", \"explainerTitle\", \"explainer\", \"safety\"];\n  fields.forEach(field => {\n    const element = treatmentDialog.querySelector(`[data-treatment-${field.replace(/[A-Z]/g, letter => `-${letter.toLowerCase()}`)}]`);\n    if (element) element.textContent = content[field];\n  });\n  replaceTextList(\"[data-treatment-goals]\", content.goals, \"item\");\n  replaceTextList(\"[data-treatment-steps]\", content.steps, \"step\");\n  replaceTextList(\"[data-treatment-areas]\", content.areas, \"tag\");\n  treatmentDialog.showModal();\n}\ndocument.querySelectorAll(\".js-open-treatment\").forEach(button => button.addEventListener(\"click\", () => openTreatment(button.dataset.treatment)));\n\nconst botulinumDialog = document.querySelector(\"#botulinum-dialog\");\ndocument.querySelectorAll(\".js-open-botulinum\").forEach(button => button.addEventListener(\"click\", () => botulinumDialog?.showModal()));\n\nconst contactDialog = document.querySelector(\"#contact-dialog\");\ndocument.querySelectorAll(\".js-open-contact\").forEach(button => button.addEventListener(\"click\", () => contactDialog?.showModal()));\ndocument.querySelector(\".js-treatment-contact\")?.addEventListener(\"click\", () => {\n  treatmentDialog?.close();\n  contactDialog?.showModal();\n});\ndocument.querySelectorAll(\"dialog .dialog-close\").forEach(button => button.addEventListener(\"click\", () => button.closest(\"dialog\")?.close()));\ndocument.querySelectorAll(\"dialog\").forEach(dialog => dialog.addEventListener(\"click\", event => {\n  const rect = dialog.getBoundingClientRect();\n  const inside = event.clientX >= rect.left && event.clientX <= rect.right && event.clientY >= rect.top && event.clientY <= rect.bottom;\n  if (!inside) dialog.close();\n}));\n\nconst form = document.querySelector(\"#contact-form\");\nconst startedAtField = form?.querySelector('[name=\"startedAt\"]');\nif (startedAtField) startedAtField.value = String(Date.now());\nform?.addEventListener(\"submit\", async event => {\n  event.preventDefault();\n  const status = form.querySelector(\".form-status\");\n  const submitButton = form.querySelector(\".form-submit\");\n  const data = new FormData(form);\n  const payload = Object.fromEntries(data.entries());\n  status.className = \"form-status\";\n  status.textContent = \"Ihre Anfrage wird sicher übermittelt …\";\n  submitButton.disabled = true;\n  submitButton.setAttribute(\"aria-busy\", \"true\");\n\n  try {\n    const response = await fetch(\"/api/contact\", {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\", \"accept\": \"application/json\" },\n      body: JSON.stringify(payload)\n    });\n    const result = await response.json().catch(() => ({}));\n    if (!response.ok) throw new Error(result.message || \"Die Anfrage konnte nicht gesendet werden.\");\n    form.reset();\n    if (startedAtField) startedAtField.value = String(Date.now());\n    status.classList.add(\"success\");\n    status.textContent = \"Vielen Dank. Ihre Anfrage wurde erfolgreich gesendet.\";\n    status.focus({ preventScroll: true });\n  } catch (error) {\n    status.classList.add(\"error\");\n    status.textContent = error instanceof Error ? error.message : \"Die Anfrage konnte nicht gesendet werden. Bitte versuchen Sie es später erneut.\";\n  } finally {\n    submitButton.disabled = false;\n    submitButton.removeAttribute(\"aria-busy\");\n  }\n});\n\nconst legalDialog = document.querySelector(\"#legal-dialog\");\nconst legalContent = {\n  Impressum: `\n    <section>\n      <h3>Anbieter</h3>\n      <p><strong>Robert Tobis</strong><br>Facharzt für Chirurgie · Facharzt für Allgemeinmedizin<br>Pestalozzistraße 27<br>08062 Zwickau</p>\n    </section>\n    <section>\n      <h3>Kontakt</h3>\n      <p>E-Mail: <a href=\"mailto:r.tobis@wp.eu\">r.tobis@wp.eu</a><br>Für Behandlungsanfragen steht zusätzlich das Kontaktformular dieser Website zur Verfügung.</p>\n    </section>\n    <section>\n      <h3>Berufsrechtliche Angaben</h3>\n      <p>Berufsbezeichnungen: Arzt, Facharzt für Chirurgie und Facharzt für Allgemeinmedizin (Deutschland)</p>\n      <p>Zuständige Kammer: Sächsische Landesärztekammer, Schützenhöhe 16, 01099 Dresden. Es gelten die Berufsordnung und das Sächsische Heilberufekammergesetz in der jeweils gültigen Fassung.</p>\n    </section>\n    <section>\n      <h3>Inhaltlich verantwortlich</h3>\n      <p>Robert Tobis, Anschrift wie oben.</p>\n    </section>\n  `,\n  Datenschutz: `\n    <section>\n      <h3>1. Verantwortlicher</h3>\n      <p>Robert Tobis<br>Pestalozzistraße 27, 08062 Zwickau<br>E-Mail: <a href=\"mailto:r.tobis@wp.eu\">r.tobis@wp.eu</a></p>\n    </section>\n    <section>\n      <h3>2. Aufruf und Hosting der Website</h3>\n      <p>Beim Aufruf der Website werden technisch erforderliche Verbindungsdaten verarbeitet. Dazu können IP-Adresse, Datum und Uhrzeit, aufgerufene Adresse, Browser- und Geräteinformationen sowie Referrer-Angaben gehören. Die Verarbeitung dient der sicheren Bereitstellung, Fehleranalyse und Abwehr von Missbrauch.</p>\n      <p>Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO. Das berechtigte Interesse liegt im sicheren und funktionsfähigen Betrieb der Website. Die Website wird über OpenAI Sites auf technischer Infrastruktur von Cloudflare bereitgestellt.</p>\n    </section>\n    <section>\n      <h3>3. Kontaktformular und E-Mail-Versand</h3>\n      <p>Bei Nutzung des Kontaktformulars werden Name, E-Mail-Adresse, der ausgewählte Interessenbereich, die Nachricht und – nur wenn freiwillig angegeben – die Telefonnummer verarbeitet. Die Angaben werden ausschließlich zur Bearbeitung und Beantwortung der Anfrage verwendet.</p>\n      <p>Bitte übermitteln Sie über das Formular keine Befunde, Diagnosen, Bilder oder sonstigen sensiblen Gesundheitsdaten. Das Formular ist nur für eine erste organisatorische Kontaktaufnahme vorgesehen.</p>\n      <p>Rechtsgrundlage ist Ihre Einwilligung gemäß Art. 6 Abs. 1 lit. a DSGVO; soweit die Anfrage auf die Anbahnung einer Behandlung gerichtet ist, zusätzlich Art. 6 Abs. 1 lit. b DSGVO. Eine erteilte Einwilligung kann jederzeit mit Wirkung für die Zukunft widerrufen werden.</p>\n      <p>Für den technischen Versand wird Brevo als Auftragsverarbeiter eingesetzt: Brevo GmbH, Köpenicker Straße 126, 10179 Berlin. Die Formulardaten werden zur Erstellung und Zustellung der Transaktions-E-Mail an Brevo übermittelt. Die weitere Bearbeitung erfolgt im E-Mail-Postfach des Verantwortlichen.</p>\n    </section>\n    <section>\n      <h3>4. Speicherdauer</h3>\n      <p>Anfragen werden nur so lange gespeichert, wie dies für ihre Bearbeitung und mögliche Anschlusskommunikation erforderlich ist. Gesetzliche Aufbewahrungspflichten bleiben unberührt. Nicht benötigte Daten werden anschließend gelöscht.</p>\n    </section>\n    <section>\n      <h3>5. Cookies und Reichweitenmessung</h3>\n      <p>Diese Website verwendet derzeit keine Analyse-, Marketing- oder Profiling-Dienste und setzt keine nicht technisch erforderlichen Cookies ein. Es findet keine automatisierte Entscheidungsfindung statt.</p>\n    </section>\n    <section>\n      <h3>6. Ihre Rechte</h3>\n      <p>Sie haben nach Maßgabe der DSGVO das Recht auf Auskunft, Berichtigung, Löschung, Einschränkung der Verarbeitung, Datenübertragbarkeit und Widerspruch. Eine Einwilligung kann jederzeit für die Zukunft widerrufen werden.</p>\n    </section>\n    <section>\n      <h3>7. Beschwerderecht</h3>\n      <p>Sie können sich bei einer Datenschutz-Aufsichtsbehörde beschweren. Zuständig ist insbesondere die Sächsische Datenschutz- und Transparenzbeauftragte, Devrientstraße 5, 01067 Dresden, <a href=\"https://www.datenschutz.sachsen.de/\" target=\"_blank\" rel=\"noopener noreferrer\">www.datenschutz.sachsen.de</a>.</p>\n    </section>\n    <section>\n      <h3>8. Datensicherheit</h3>\n      <p>Die Übertragung erfolgt verschlüsselt über HTTPS. Technische Schutzmaßnahmen begrenzen missbräuchliche Formularanfragen. Der für den E-Mail-Versand erforderliche Zugangsschlüssel wird verschlüsselt und nicht im öffentlich abrufbaren Seiteninhalt gespeichert.</p>\n    </section>\n    <p class=\"legal-note\">Stand: Oktober 2026. Diese Erklärung wird angepasst, wenn sich eingesetzte Dienste oder Verarbeitungsabläufe ändern.</p>\n  `\n};\ndocument.querySelectorAll(\".js-legal\").forEach(button => button.addEventListener(\"click\", () => {\n  const key = button.dataset.legal;\n  legalDialog.querySelector(\"#legal-title\").textContent = key === \"Datenschutz\" ? \"Datenschutzerklärung\" : \"Impressum\";\n  legalDialog.querySelector(\"#legal-content\").innerHTML = legalContent[key] || \"\";\n  legalDialog.showModal();\n}));\n\nconst observer = \"IntersectionObserver\" in window ? new IntersectionObserver(entries => {\n  entries.forEach(entry => {\n    if (entry.isIntersecting) {\n      entry.target.classList.add(\"visible\");\n      observer.unobserve(entry.target);\n    }\n  });\n}, { threshold: .12 }) : null;\ndocument.querySelectorAll(\".reveal\").forEach(element => observer ? observer.observe(element) : element.classList.add(\"visible\"));\ndocument.querySelector(\"#year\").textContent = new Date().getFullYear();\n</script>\n</body>\n</html>\n";
const ASSETS = {"/assets/hero-premium.webp":{"type":"image/webp","body":""},"/assets/portrait-premium.webp":{"type":"image/webp","body":""},"/assets/botulinum-portrait.webp":{"type":"image/webp","body":""}};

const responseHeaders = {
  "x-content-type-options": "nosniff",
  "referrer-policy": "strict-origin-when-cross-origin",
  "permissions-policy": "camera=(), microphone=(), geolocation=()",
};

const rateLimit = new Map();
const allowedInterests = new Set([
  "Allgemeine Beratung",
  "Botulinumtoxin",
  "Hyaluronsäure",
  "PRP / PRF / autologe Exosomen",
]);

function json(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...responseHeaders, "content-type": "application/json; charset=utf-8", "cache-control": "no-store" },
  });
}

function clean(value, maxLength) {
  return String(value ?? "").replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "").trim().slice(0, maxLength);
}

function escapeHtml(value) {
  return value.replace(/[&<>"']/g, character => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#039;" })[character]);
}

function base64ToBytes(value) {
  return Uint8Array.from(atob(value), character => character.charCodeAt(0));
}

async function getEncryptionKey(env) {
  if (!env.CONFIG_ENCRYPTION_KEY) throw new Error("Missing encryption key");
  return crypto.subtle.importKey("raw", base64ToBytes(env.CONFIG_ENCRYPTION_KEY), { name: "AES-GCM" }, false, ["encrypt", "decrypt"]);
}

async function readSecret(name, env) {
  if (!env.DB) throw new Error("Database unavailable");
  const row = await env.DB.prepare("SELECT ciphertext, iv FROM site_secrets WHERE name = ? LIMIT 1").bind(name).first();
  if (!row) return null;
  const key = await getEncryptionKey(env);
  const plaintext = await crypto.subtle.decrypt({ name: "AES-GCM", iv: base64ToBytes(row.iv) }, key, base64ToBytes(row.ciphertext));
  return new TextDecoder().decode(plaintext);
}

function isRateLimited(request) {
  const ip = request.headers.get("cf-connecting-ip") || "unknown";
  const now = Date.now();
  const windowStart = now - 10 * 60 * 1000;
  const attempts = (rateLimit.get(ip) || []).filter(timestamp => timestamp > windowStart);
  attempts.push(now);
  rateLimit.set(ip, attempts);
  return attempts.length > 4;
}

async function sendContact(request, env) {
  const origin = request.headers.get("origin");
  if (origin && origin !== new URL(request.url).origin) return json({ message: "Ungültige Anfrage." }, 403);
  if (!request.headers.get("content-type")?.toLowerCase().includes("application/json")) return json({ message: "Ungültiges Format." }, 415);
  if (Number(request.headers.get("content-length") || 0) > 20_000) return json({ message: "Die Anfrage ist zu groß." }, 413);
  if (isRateLimited(request)) return json({ message: "Zu viele Anfragen. Bitte versuchen Sie es später erneut." }, 429);

  let input;
  try {
    input = await request.json();
  } catch {
    return json({ message: "Die Anfrage konnte nicht gelesen werden." }, 400);
  }

  if (clean(input.website, 200)) return json({ ok: true });
  const elapsed = Date.now() - Number(input.startedAt || 0);
  if (!Number.isFinite(elapsed) || elapsed < 2500 || elapsed > 2 * 60 * 60 * 1000) return json({ message: "Bitte laden Sie das Formular neu und versuchen Sie es erneut." }, 400);

  const name = clean(input.name, 120);
  const email = clean(input.email, 200).toLowerCase();
  const phone = clean(input.phone, 40);
  const interest = clean(input.interest, 80);
  const message = clean(input.message, 2000);
  const privacy = input.privacy === "on" || input.privacy === true || input.privacy === "true";
  if (name.length < 2 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || !allowedInterests.has(interest) || !privacy) {
    return json({ message: "Bitte prüfen Sie die Pflichtfelder und Ihre E-Mail-Adresse." }, 400);
  }
  if (phone && !/^[0-9+()\s./-]{5,40}$/.test(phone)) return json({ message: "Bitte prüfen Sie die Telefonnummer oder lassen Sie das Feld frei." }, 400);
  let apiKey;
  try { apiKey = await readSecret("brevo_api_key", env); } catch (error) {
    console.error("Encrypted contact configuration unavailable", error instanceof Error ? error.message : "unknown");
    return json({ message: "Das Kontaktformular ist derzeit nicht verfügbar." }, 503);
  }
  if (!apiKey) return json({ message: "Das Kontaktformular ist noch nicht vollständig freigeschaltet." }, 503);

  const recipient = env.CONTACT_RECIPIENT || "r.tobis@wp.eu";
  const sender = env.BREVO_SENDER_EMAIL || "r.tobis@wp.eu";
  const safeName = escapeHtml(name);
  const safeEmail = escapeHtml(email);
  const safePhone = escapeHtml(phone || "nicht angegeben");
  const safeInterest = escapeHtml(interest);
  const safeMessage = escapeHtml(message || "—").replace(/\n/g, "<br>");
  const subject = `Anfrage Ästhetische Medizin – ${interest}`;
  const textContent = [
    `Name: ${name}`,
    `E-Mail: ${email}`,
    `Telefon: ${phone || "nicht angegeben"}`,
    `Interesse: ${interest}`,
    "",
    "Nachricht:",
    message || "—",
  ].join("\n");
  const htmlContent = `<h2>Neue Anfrage über die Website</h2><p><strong>Name:</strong> ${safeName}<br><strong>E-Mail:</strong> ${safeEmail}<br><strong>Telefon:</strong> ${safePhone}<br><strong>Interesse:</strong> ${safeInterest}</p><p><strong>Nachricht:</strong><br>${safeMessage}</p><hr><p style="color:#64748b;font-size:12px">Antworten Sie auf diese E-Mail, um direkt an die anfragende Person zu schreiben.</p>`;

  const brevoResponse = await fetch("https://api.brevo.com/v3/smtp/email", {
    method: "POST",
    headers: { "accept": "application/json", "api-key": apiKey, "content-type": "application/json" },
    body: JSON.stringify({
      sender: { name: "Robert Tobis – Ästhetische Medizin", email: sender },
      to: [{ name: "Robert Tobis", email: recipient }],
      replyTo: { name, email },
      subject,
      textContent,
      htmlContent,
    }),
  });

  if (!brevoResponse.ok) {
    console.error("Brevo contact request failed", brevoResponse.status);
    return json({ message: "Die Anfrage konnte derzeit nicht gesendet werden. Bitte versuchen Sie es später erneut." }, 502);
  }
  return json({ ok: true });
}

export default {
  async fetch(request, env, ctx) {
    void ctx;
    const url = new URL(request.url);
    if (url.pathname === "/api/contact") {
      if (request.method !== "POST") return json({ message: "Methode nicht erlaubt." }, 405);
      return sendContact(request, env);
    }
    if (request.method !== "GET" && request.method !== "HEAD") return new Response("Method not allowed", { status: 405, headers: responseHeaders });
    if (url.pathname === "/" || url.pathname === "/index.html") {
      return new Response(request.method === "HEAD" ? null : PAGE, {
        headers: { ...responseHeaders, "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=300" },
      });
    }
    const asset = ASSETS[url.pathname];
    if (asset) {
      const bytes = Uint8Array.from(atob(asset.body), character => character.charCodeAt(0));
      return new Response(request.method === "HEAD" ? null : bytes, {
        headers: { ...responseHeaders, "content-type": asset.type, "cache-control": "public, max-age=31536000, immutable" },
      });
    }
    return new Response("Not found", { status: 404, headers: responseHeaders });
  },
};
